import{_ as d,a as t,c as a,ac as s}from"./chunks/framework.BSuaGltH.js";const h=JSON.parse('{"title":"Redis 配置","description":"redis 安装以及基本使用 、配置 ","frontmatter":{"title":"Redis 配置","description":"redis 安装以及基本使用 、配置 ","sources":[{"repository":"jekyall_blog","file":"_posts/DataStorage/redis/not/redis-config.md","date":"Sat Jan 26 2019 12:48:54 GMT+0800 (中国标准时间)"}],"showdocs":{"topics":[{"id":"redis","title":"Redis","link":"/topics/redis/"}],"kind":"数据与原子性","scope":"historical","audience":"general","group":"数据库与存储","summary":"redis 安装以及基本使用 、配置 ","status":"active","related":[{"title":"CentOS 7 与 Redis 4.0.1 安装笔记","link":"/middleware/redis/plus/subjects/redis-centos-7","kind":"数据与原子性","scope":"historical","audience":"general"},{"title":"Redis 持久化：RDB、AOF 与独立恢复","link":"/middleware/redis/persistence-and-recovery","kind":"数据与原子性","scope":"general","audience":"general"},{"title":"Redis 键管理：数量、扫描与过期时间","link":"/middleware/redis/key-lifecycle","kind":"数据与原子性","scope":"general","audience":"general"},{"title":"Redis 起点与命令：隔离服务、连接与键空间","link":"/middleware/redis/base/basic/start","kind":"数据与原子性","scope":"general","audience":"general"},{"title":"Redis 数据操作：结构、TTL、事务与 Lua","link":"/middleware/redis/data-operations","kind":"数据与原子性","scope":"general","audience":"general"}],"prev":false,"next":{"text":"Redis、日志与工程维护脚本","link":"/middleware/redis/plus/subjects/redis-py-utils"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"Redis、日志与工程维护脚本","link":"/middleware/redis/plus/subjects/redis-py-utils"}},"headers":[],"relativePath":"middleware/redis/plus/subjects/redis-config.md","filePath":"middleware/redis/plus/subjects/redis-config.md"}'),i={name:"middleware/redis/plus/subjects/redis-config.md"};function o(r,e,n,c,l,p){return t(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="redis-配置" tabindex="-1">Redis 配置 <a class="header-anchor" href="#redis-配置" aria-label="Permalink to &quot;Redis 配置 {#redis-配置}&quot;">​</a></h1><p>先查运行实例的实际值，再决定运行时修改还是更新启动配置。末尾保留原笔记的完整历史配置，按需要展开；它不是当前版本的可直接部署模板。</p><p><span id="redis-config" aria-hidden="true"></span></p><h2 id="inspect" tabindex="-1">确认实例与生效配置 <a class="header-anchor" href="#inspect" aria-label="Permalink to &quot;确认实例与生效配置 {#inspect}&quot;">​</a></h2><p>在已认证连接中查看版本与有关配置，避免第一次就导出全部配置：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>INFO server</span></span>
<span class="line"><span>CONFIG GET bind</span></span>
<span class="line"><span>CONFIG GET port</span></span>
<span class="line"><span>CONFIG GET save</span></span>
<span class="line"><span>CONFIG GET appendonly</span></span>
<span class="line"><span>CONFIG GET maxmemory</span></span>
<span class="line"><span>CONFIG GET maxmemory-policy</span></span></code></pre></div><p><code>CONFIG</code> 是否允许调用取决于权限与服务策略。命令语法是 <code>CONFIG SET 参数 值</code>，不是 <code>CONFIG SETS</code>；并非所有启动参数都能运行时修改。</p><h2 id="settings" tabindex="-1">按需求找到配置项 <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;按需求找到配置项 {#settings}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>要处理的事情</th><th>查哪些项</th><th>判断要点</th></tr></thead><tbody><tr><td>监听与访问</td><td><code>bind</code>、<code>port</code>、<code>protected-mode</code>、ACL/TLS 相关项</td><td><code>bind</code> 是绑定地址，旧表的 <code>buid</code> 是拼写错误；访问控制不能只靠端口</td></tr><tr><td>客户端连接</td><td><code>timeout</code>、<code>maxclients</code></td><td>空闲连接与最大连接数不同，连接数还受系统文件描述符等限制</td></tr><tr><td>日志</td><td><code>loglevel</code>、<code>logfile</code></td><td><code>logfile &quot;&quot;</code> 表示标准输出；结合进程管理方式确认实际日志位置</td></tr><tr><td>内存与淘汰</td><td><code>maxmemory</code>、<code>maxmemory-policy</code></td><td>设置可淘汰数据范围，并为复制、持久化及系统开销留空间</td></tr><tr><td>RDB 快照</td><td><code>save</code>、<code>dbfilename</code>、<code>dir</code></td><td>保存条件、文件名与目录；写入权限和磁盘空间都要验证</td></tr><tr><td>AOF 日志</td><td><code>appendonly</code>、<code>appendfsync</code> 及目标版本的文件布局项</td><td>持久性、重写资源和恢复流程一起评估</td></tr><tr><td>复制与分片</td><td>目标版本的 <code>replicaof</code>、复制积压、<code>cluster-*</code> 等</td><td>先明确主从、Sentinel 或 Cluster 拓扑</td></tr><tr><td>逻辑数据库</td><td><code>databases</code></td><td>单实例的逻辑库不是隔离的独立服务；Cluster 只使用库 0</td></tr></tbody></table><p>原笔记中的 <code>save 900 1</code>、<code>save 300 10</code>、<code>save 60 10000</code> 表示三组快照触发条件，不代表所有 Redis 版本的默认值。先看实际 <code>CONFIG GET save</code> 与目标版本配置。</p><h2 id="change" tabindex="-1">运行时修改与持久保存 <a class="header-anchor" href="#change" aria-label="Permalink to &quot;运行时修改与持久保存 {#change}&quot;">​</a></h2><ol><li>记录当前值、修改目的与恢复值，并确认命令属于允许在线调整的参数。</li><li>通过 <code>CONFIG SET</code> 调整后，用 <code>CONFIG GET</code> 复核，不把返回 <code>OK</code> 直接当作业务验证。</li><li>决定由哪个配置源持久管理：人工配置文件、部署模板或管理服务。</li><li><code>CONFIG REWRITE</code> 尝试更新实例使用的配置文件，不等于同步修改部署系统里的模板；文件不可写、没有配置文件或受管服务都可能限制它。</li><li>在隔离/预发布环境重启核对持久值，并验证客户端连接、内存和持久化指标。</li></ol><p>不要同时由在线命令与模板各维护一份相互冲突的配置。多节点修改要按角色逐个确认，不把单节点返回值当成集群全部生效。</p><h2 id="troubleshooting" tabindex="-1">常见问题从哪里查 <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;常见问题从哪里查 {#troubleshooting}&quot;">​</a></h2><ul><li><strong>重启后恢复旧值</strong>：检查启动参数、最终配置路径、include 顺序，以及部署模板是否覆盖在线修改。</li><li><strong>客户端连不上</strong>：核对监听地址/端口、网络可达性、ACL/TLS 和客户端身份；不要仅为连通就关闭访问控制。</li><li><strong>写入内存错误</strong>：核对 <code>maxmemory</code>、策略候选范围及键大小，不将过期与淘汰当成同一机制。</li><li><strong>持久化失败或延迟升高</strong>：检查磁盘、目录权限、后台保存/重写状态和复制开销。</li></ul><p>机制比较见 <a href="/middleware/redis/pro/interview/redis-面试">Redis 知识复盘</a>。</p><p><span id="redis-conf-待完善" aria-hidden="true"></span></p><h2 id="historical-config" tabindex="-1">完整历史 redis.conf <a class="header-anchor" href="#historical-config" aria-label="Permalink to &quot;完整历史 redis.conf {#historical-config}&quot;">​</a></h2><p>以下配置保留原来的中文注释、指令与英文附注，用于对照字段。原文含“保护模式是”“设备在中间。”等未加 <code>#</code> 的翻译残片，因此整块不是语法有效的 redis.conf，不应直接交给服务端加载；残片保持原样以便追溯。实际采用前应从目标 Redis 版本随附配置重新确认支持的参数及默认值。</p><details><summary>展开完整历史配置</summary><p>完整文件：<a href="/article-files/25aab147e0b570f6.txt" download="">完整历史 redis.conf（txt）</a>。保留原始内容，使用前请核对本文的版本与环境说明。</p></details>`,20)])])}const m=d(i,[["render",o]]);export{h as __pageData,m as default};
